def semver_sort(versions):
    def parse_version(version):
        # Split build metadata (everything after '+')
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version

        # Split pre-release (everything after '-')
        if '-' in version_part:
            core, prerelease = version_part.split('-', 1)
        else:
            core = version_part
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_parts = prerelease.split('.')
            # Convert identifiers: numbers stay as ints, strings stay as strings
            prerelease_parsed = []
            for part in prerelease_parts:
                if part.isdigit():
                    prerelease_parsed.append((0, int(part)))  # 0 prefix: numeric
                else:
                    prerelease_parsed.append((1, part))  # 1 prefix: string
        else:
            prerelease_parsed = None

        return (major, minor, patch, prerelease_parsed)

    def compare_key(version_tuple):
        major, minor, patch, prerelease_parsed = version_tuple

        # For sorting: (major, minor, patch, has_prerelease, prerelease_parts)
        # If prerelease_parsed is None, it sorts AFTER versions with prerelease
        if prerelease_parsed is None:
            # No prerelease: sorts after with prerelease
            return (major, minor, patch, 1, [])
        else:
            # Has prerelease: sorts before without prerelease
            return (major, minor, patch, 0, prerelease_parsed)

    # Parse all versions with their original index for stable sort
    parsed = [(parse_version(v), i, v) for i, v in enumerate(versions)]

    # Sort by compare_key, then by original index for stability
    parsed.sort(key=lambda x: (compare_key(x[0]), x[1]))

    # Return sorted version strings
    return [v for _, _, v in parsed]

